-- Rifts World Book 2: Atlantis - the magic tattoos (printed 86-93), 32 rows,
-- as spells with tradition 'tattoo'. See apps/character-creator/docs/surveys/atlantis.md.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-atlantis-tattoos.sql
--
-- READ FROM A SCAN. The book has no text layer; these rows come from the OCR
-- cache (.cache/books/atlantis, page_offset 0), repaired where the OCR set a
-- section sign for S or a bar for 1. Costs were checked against renders of
-- printed 92 and 93.
--
-- WHY SPELLS: Nate's decision on the survey, 2026-09-26, following South
-- America 2's Nazca line drawings (tradition 'nazca'): each tattoo prints a
-- P.P.E. cost, a duration and an effect, the spell columns. `Tattoo: ` prefix,
-- tradition 'tattoo', LEVEL 0 - no tattoo prints a level. Activation counts as
-- one melee action (printed 85), stored as casting_time.
--
-- NAMES are the entry headings, with the book's own parenthetical label, so a
-- picker reads "Heart with Large Wings (fly)". The 22 power tattoos reconcile
-- with the Tattoo Index by Power Type (printed 91): its 25 index lines map to
-- the 22 images (Phoenix covers super healing and resurrection, Eye With Tears
-- empathy and transmission, Shark or Dolphin swim and breathe without air),
-- and every index cost equals its entry's.
--
-- ANIMAL and MONSTER are one row each, as Nazca's Lesser Animal and Monster
-- Drawings are: the book prices both by size tier (ppe holds the minimum,
-- ppe_note the schedule), and the animal list is carried in the description.
--
-- EVERY ppe_note says the cost is DOUBLE for anyone who is not a full
-- Tattooed Man (printed 85) - wizards, cyber-knights and True Atlanteans with
-- their Marks of Heritage.
--
-- NOT HERE: who may receive tattoos (humans, True Atlanteans, ogres, elves at
-- a penalty, Chiang-Ku - printed 85) and the pain of receiving them (printed
-- 84-85) are rules for the classes, which carry them.

INSERT OR IGNORE INTO spells
  (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition)
VALUES
  ('Tattoo: All Simple Weapons', 0, 2, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.86', 'rifts', NULL, '30 minutes per level of experience or until cancelled', 'The normal S.D.C. damage for that type of weapon', NULL, NULL, 'One melee action', 'Image: any ancient hand to hand weapon - axe, boomerang, ball and chain, club, mace, war hammer, knife, sword, spear, bow and arrow, and exotic weapons like tiger claws and shuriken. Creates the weapon illustrated in the tattoo out of thin air. The weapon is lightweight, perfectly balanced, never dulls and is indestructible, and vanishes when the magic is cancelled or the duration ends. Modern weapons, revolvers, rifles, automatic and energy weapons are not possible. W.P. skills and bonuses apply, but the W.P. must be selected separately. The size of the weapon is always proportional to the size of the T-Man. The weapon continues to exist if the user is rendered unconscious, possessed or mind controlled; a controlling force cannot activate or cancel tattoos. Anybody can use a tattoo weapon as long as the T-Man allows it, and he can cancel it with a thought. None of the weapon''s powers can be transferred to living beings or modern weapons. Each weapon is a separate tattoo; the same image cannot be duplicated on one person.', NULL, 'tattoo'),
  ('Tattoo: S.D.C. Shield', 0, 4, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.86', 'rifts', NULL, '30 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Creates the shield illustrated in the tattoo out of thin air. The shield is lightweight, perfectly balanced, and has 200 S.D.C. and an A.R. of 13. Vanishes when the S.D.C. is depleted, the magic is cancelled or the duration ends. The size of the shield is always proportional to the size of the T-Man. Bonus: +1 to parry in addition to any W.P. skill or P.P. bonuses. The shield continues to exist even when the user is rendered unconscious, possessed, or mind controlled.', NULL, 'tattoo'),
  ('Tattoo: Two Weapons Crossed', 0, 5, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.87', 'rifts', NULL, '15 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'The T-Man is +1 to strike and +2 to parry with any type of weapon that falls into the category crossed in the tattoo, whether one of his tattoo weapons or a normal weapon. The bonuses are in addition to any combat or W.P. skills. Crossbows and bows and arrows are NOT included with this type of tattoo. Magic weapon tattoos create an indestructible hand to hand weapon with special properties; a weapon may combine more than one magic feature (a flaming axe with wings inflicts mega-damage, has triple range when thrown and returns).', NULL, 'tattoo'),
  ('Tattoo: Weapon Dripping Blood', 0, 5, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.87', 'rifts', NULL, '15 minutes per level of experience or until cancelled', 'Double the usual S.D.C. damage for the weapon', NULL, NULL, 'One melee action', 'The weapon, whether an arrow, dagger, sword, club or whatever, inflicts double the usual amount of S.D.C. damage for that particular weapon. Magic weapon tattoos create an indestructible hand to hand weapon; modern and energy weapons are not possible, and W.P. skills apply but must be selected separately.', NULL, 'tattoo'),
  ('Tattoo: Weapon Covered in Flames', 0, 10, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.87', 'rifts', NULL, '15 minutes per level of experience or until cancelled', 'The weapon''s usual S.D.C. damage as mega-damage', NULL, NULL, 'One melee action', 'The weapon, whether a dagger, sword, club, arrow or whatever, inflicts the mega-damage equivalent of the usual S.D.C. damage: if a normal short sword inflicts 1D6 S.D.C., a magic short sword created by the tattoo inflicts 1D6 M.D. Magic weapon tattoos create an indestructible hand to hand weapon; modern and energy weapons are not possible.', NULL, 'tattoo'),
  ('Tattoo: Weapon Covered in Flames and a Coiled Snake/Serpent', 0, 20, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.88', 'rifts', NULL, '15 minutes per level of experience or until cancelled', 'Mega-damage; triple against dragons, sea serpents, dinosaurs, giant reptiles and supernatural reptilians', NULL, NULL, 'One melee action', 'The weapon, whether an arrow, dagger, sword or whatever, inflicts mega-damage, and three times the normal amount of mega-damage when used against dragons, sea serpents, dinosaurs, giant reptiles, and supernatural reptilians (like the dybbuk, sowki and gargoyles). A weapon inflicting 2D6 M.D. inflicts 6D6 M.D. against a dragon or dinosaur.', NULL, 'tattoo'),
  ('Tattoo: Weapon with Wings', 0, 5, 'An ADDITIONAL cost on top of the weapon: 5 if a simple weapon (S.D.C. damage), 10 if dripping blood (double S.D.C. damage), 20 if flame covered (M.D. weapon), 30 if flame and serpent covered (M.D. weapon that does triple damage against reptiles). Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.88', 'rifts', 'Three times the weapon''s usual effective range', '15 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'The wing feature is added to a weapon tattoo. The weapon can be thrown, or arrows fired, three times farther than the usual effective range, and it automatically returns to the Tattooed Man immediately afterwards. Typically four arrows in the tattoo; one of any other type of weapon.', NULL, 'tattoo'),
  ('Tattoo: Flaming Shield', 0, 15, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.88', 'rifts', NULL, '15 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Creates the shield illustrated in the tattoo out of thin air. The shield is lightweight, perfectly balanced, and completely indestructible. Vanishes when the magic is cancelled or the duration ends. The size of the shield is always proportional to the size of the T-Man. Bonus: +2 to parry in addition to any W.P. skill or P.P. bonuses. The shield continues to exist even when the user is rendered unconscious, possessed, or mind controlled.', NULL, 'tattoo'),
  ('Tattoo: Animals', 0, 10, '10 for small animals with less than 12 hit points, 15 for medium size animals with less than 30 hit points, 20 for medium size animals with less than 50 hit points, 30 for large animals with over 50 hit points. Twice the cost to re-create an animal that was destroyed, or wait four hours. Double for anyone who is not a full Tattooed Man (printed 85).', 'Canine: Fox, Coyote, Jackal, or Small Dogs prints track by smell 0% (clean ink on a render of printed 89); the South America 2 reprint of the same list prints 60%.', 'import', 'Rifts World Book 2: Atlantis p.88-90', 'rifts', NULL, 'One hour per level of the Tattooed Man''s experience, or until slain by depleting its S.D.C. and hit points, or the magic is cancelled', 'S.D.C. only', NULL, NULL, 'One melee action', 'Image: a specific animal, insect or arachnid; each animal is a separate tattoo and the same one cannot be duplicated on one person. The tattoo glows, leaves the body and reappears as a dull grey, life size animal protector made of a magic, ectoplasm-like substance, completely obedient to its creator and fighting to the death on verbal command. It acts like the real animal in every way. Animals are S.D.C. and hit point creations with the maximum hit points possible (small animals no S.D.C., medium 10, large 100-500 lbs 40, very large 501 lbs or more 80), and inflict only S.D.C. damage; none is a mega-damage creature. They are trained pets, not familiars: the T-Man is not mentally linked to the creature. Destroying the animal inflicts 3D6 damage direct to its owner''s hit points, cumulative for each living tattoo destroyed. Palladium''s Book of Monsters & Animals may be used for stats (give such animals one additional attack per melee). A Variety of Animals: Ape: Chimpanzee: The same size and behavior as the real animal. 48 hit points and 40 S.D.C. Bite inflicts 2D4 S.D.C. damage, slashing and tearing hands do 2D4+3 damage. Three attacks per melee. +3 to strike, +2 to parry and dodge, and can use simple weapons such as clubs, knives, swords, etc. Average spd is 10. Nightvision 15 feet (4.6 m), climb 60%, leap up to 10 feet (3 m). Ape: Gorilla: The same size and behavior as the real animal. 80 hit points and 80 S.D.C. Bite inflicts 2D4 S.D.C. damage, slashing and tearing hands do 2D6+6 damage. Four attacks per melee. +3 to strike, +3 to parry, +1 to dodge, and can use simple weapons such as clubs, knives, swords, etc. Average spd is 12. Nightvision 15 feet (4.6 m), climb 40%, and prowl 40%. Baboon: The same size and behavior as the real animal. 48 hit points and 10 S.D.C. Bite inflicts 2D6+3 S.D.C. damage, slashing and tearing hands do 2D4+2 damage. Three attacks per melee. +3 to strike, +2 to parry and dodge. Average spd is 12. Nightvision 40 feet (12.2 m), exceptional vision and hearing, track by smell 45%. Badger & Wolverine: The same size and behavior as the real animals. 30 hit points and 10 S.D.C. Bite or slashing claws do 1D6+2 S.D.C. damage. Three attacks per melee. +1 to strike and parry, and +3 to dodge. Average spd is 12. Nightvision 50 ft (15.2 m), track by smell 65%, and dig 5 feet (1.5 m) per minute. Bear: Black and Brown: The same size and behavior as a real bear. 66 hit points, 80 S.D.C. Bite does 1D8+2 S.D.C. damage, slashing claws 2D6+6 damage, pouncing/ram does 1D6+4 and has a 1-50% chance of knocking its opponent down (victim loses initiative and one melee attack), but counts as two attacks. Three attacks per melee. +2 to strike and parry, +1 to dodge. Average spd is 22 but can run in bursts of speed at 30 mph (48 km) for up to 15 minutes. Bear: Grizzly: The same size and behavior as a real bear. 120 hit points, 80 S.D.C. Bite does 1D8+6 S.D.C. damage, slashing claws 2D6+8 damage, pouncing/ram does 2D6+4 and has a 1-62% chance of knocking its opponent down (victim loses initiative and one melee attack), but counts as two attacks. Four attacks per melee. +2 to strike and parry, +1 to dodge. Average spd is 16 but can run in bursts of speed up to 20 mph (32 km) for up to 15 minutes. Bird: Hawk or Falcon: The same size and behavior as the real animals. 16 hit points and no S.D.C. Bite 1D6 S.D.C. damage, slashing claws inflict 1D4+2 damage, and a diving claw attack 2D4+2 damage, but counts as two attacks. Three attacks per melee, +2 to strike and parry and +3 to dodge. Average speed flying is 50, about 35 mph (56 km). Nightvision 300 feet (91.5 m), exceptional vision and hearing, and track by smell 65%. Bird: Eagle: The same size and behavior as the real animal. 24 hit points and 10 S.D.C. Bite 2D4 S.D.C. damage, slashing claws inflict 2D6+4 damage, and a diving claw attack 4D6+4 damage, but counts as two attacks, Four attacks per melee, +2 to strike and parry and +3 to dodge. Average speed flying is 50, about 35 mph (56 km), but can attain a speed of 75 mph (120 km) and maintain that speed for an hour. Nightvision 400 feet (122 m), exceptional vision and hearing, and track by smell 46%. Boar or Wild Pig: The same size and behavior as the real animals. 40 hit points and 40 S.D.C. Bite/slashing tusks does 1D8+2 S.D.C. damage, head butt does 1D6+2, ram does 2D6+4 and has a 1-55% chance of knocking its opponent down (victim loses initiative and one melee attack), but counts as two attacks. Three attacks per melee. +1 to strike, and +2 to dodge. Average spd is 22 but can run in bursts of speed at 35 mph (56 km) for up to 30 minutes. Canine: Fox, Coyote, Jackal, or Small Dogs: The same size and behavior as the real animals. 24 hit points, 10 S.D.C. Bite does 1D6+4 S.D.C. damage, slashing claws 1D4 damage, Three attacks per melee. +1 to strike and parry, +4 to dodge. Average spd is 50, about 35 mph (56 km) and can run at that speed for 1D6 hours. Track by smell 0%, swim 50%, keen vision and hearing. Canine: Wolf or Large Dogs: The same size and behavior as the real animals. 48 hit points, 40 S.D.C. Bite does 2D6+8 S.D.C. damage, slashing claws 1D4 damage, three attacks per melee. +3 to strike, +1 to parry, +6 to dodge. Average spd is 50, about 35 mph (56 km), and can run at that speed for 2D4 hours. Track by smell 85%, swim 65%, prowl 50%, keen vision and hearing, and nightvision 30 ft (9 m). Elephant: The same size and behavior as the real animal. It can be ridden by the Tattooed Man who created it. 90 hit points and 80 S.D.C. Three attacks per melee, tusk inflicts 2D6+6 S.D.C. damage, strike from trunk 1D6, leg kick/stomp 3D6+6 damage, head butt does 3D6+6, and a ramming charge and trample inflicts 6D6+6 damage and has an 80% likelihood of knocking opponents weighing less than 1000 lbs to the ground, causing them to lose one melee attack and initiative (counts as two attacks). Average spd is 10, about five mph (8 km), but can run as fast as 35 mph (56 km) for 30 minutes. Keen hearing and sense of smell, good vision, nightvision 40 ft (12.2 m), swim 90% and has prehensile trunk. Feline: African Lion: The same size and behavior as the real animal. 52 hit points, 80 S.D.C. Bite does 2D4 S.D.C. damage, slashing claws 2D6+6 damage, four attacks per melee. +3 to strike and parry, +4 to dodge. Average spd is 22, about 15 mph (24 km), but can run in bursts at a speed of 25 mph (40 km) for 1D4 minutes. Track by smell 70%, swim 50%, prowl 70%, climb 30%, leap up to 15 feet high (4.6 m) and 20 feet long (6 m), keen vision and hearing, and nightvision 60 ft (18.3 m). Feline: Bobcat, Lynx, Mountain Lion: The same size and behavior as the real animals. 42 hit points, 40 S.D.C. Bite does 1D6 S.D.C. damage, slashing claws 2D4+3 damage, four attacks per melee. +3 to strike and parry, +4 to dodge. Average spd is 22, about 15 mph (24 km), but can run in bursts at a speed of 30 mph (48 km) for 1D4 minutes. Swim 44%, prowl 86%, climb 90%, leap up to 20 feet high (6 m) and 20 feet long (6 m), keen vision and hearing, and nightvision 60 ft (18.3 m). Feline: Cheetah: The same size and behavior as the real animal. 48 hit points, 40 S.D.C. Bite does 1D6 S.D.C. damage, slashing claws 2D4+6 damage, four attacks per melee. +4 to strike and parry, +6 to dodge. Average spd is 22, about 15 mph (24 km), but can run in bursts of incredible speed - 80 mph (128 km) for 1D4 minutes. Track by smell 50%, swim 55%, prowl 50%, climb 45%, leap up to 10 feet high (3 m) and 15 feet across (4.6 m), keen vision and hearing, and nightvision 30 ft (9 m). Feline: Leopard & Panther: The same size and behavior as the real animals. 48 hit points, 40 S.D.C. Bite does 1D6 S.D.C. damage, slashing claws 2D4+3 damage, four attacks per melee. + 3 to strike and parry, +4 to dodge. Average spd is 22, about 15 mph (24 km), but can run in bursts at a speed of 35 mph (56 km) for 1D4 minutes. Track by smell 50%, swim 80%, prowl 90%, climb 75%, leap up to 20 feet high (6 m) and 40 feet across (12.2 m), keen vision and hearing, and nightvision 60 ft (18.3 m). Feline: Tiger: The same size and behavior as the real animal. 68 hit points, 80 S.D.C. Bite does 2D6 S.D.C. damage, slashing claws 2D6+8 damage, four attacks per melee. +3 to strike and parry, +4 to dodge. Average spd is 22, about 15 mph (24 km), but can run in bursts at a speed of 35 mph (56 km) for 1D4 minutes. Track by smell 50%, swim 80%, prowl 70%, climb 50%, leap up to 20 feet high (6 m) and 25 feet long (7.6 m), keen vision and hearing, and nightvision 60 ft (18.3 m). Ferret, Mink, or Martin: The same size and behavior as the real animals. 12 hit points and no S.D.C. Bite and slashing claws inflict 1D4 S.D.C. damage. Three attacks per melee, +1 to strike and parry and +4 to dodge. Average spd is 10. Nightvision 40 feet (12.2 m), exceptional vision and hearing, track by smell 65%, climb 50%, prowl 65%, and swim 70%. Horse: The same size and behavior as the real animal. It can be ridden by the Tattooed Man who created it. 48 hit points and 80 S.D.C. Three attacks per melee, bite inflicts 1D4 S.D.C. damage, front leg kick 2D6 damage, hind leg kick 4D6 damage, charging head butt does 2D4+10 and has an 80% likelihood of knocking opponents weighing less than 300 lbs to the ground, causing them to lose one melee attack and initiative (counts as two attacks). Average spd is 33, about 22 mph (36 km), but can run as fast as 45 mph (72 km) for 1D4 hours, Can also leap up to six feet high (1.8 m) and 12 feet long (3.6 m), keen hearing, and swim 50%. Monkey: The same size and behavior as the real animal. 32 hit points and 10 S.D.C. Bite and slashing/tearing hands inflict 1D6+1 S.D.C. damage. Three attacks per melee, +3 to strike and parry and +5 to dodge. Average spd is 12, Nightvision 25 feet (7.6 m), exceptional vision and hearing, climb 95%, acrobatics 95%, leap 8 ft high (2.4 m) and 20 feet (6 m) across in trees, prehensile tail. Rhinoceros: The same size and behavior as the real animal. It can be ridden by the Tattooed Man who created it. 84 hit points and 80 S.D.C. Two attacks per melee, jab with horn inflicts 2D6+4 S.D.C. damage, leg kick/stomp 3D6+4 damage, head butt with horn does 3D6+4, and a ramming charge and trample inflicts 4D6+6 damage and has an 80% likelihood of knocking opponents weighing less than 1000 lbs to the ground, causing them to lose one melee attack and initiative (counts as two attacks). Average spd is 14, about seven mph (11 km), but can run as fast as 30 mph (48 km) for 12 minutes. Keen hearing and sense of smell, poor vision, and swim 40%. Scorpion: The same size as a common scorpion, it behaves as a living scorpion would, its sting is poisonous. Three attacks per melee, +2 to strike and dodge, spd 8, and can climb most surfaces except glass or highly polished metal. . Spider (non-poisonous): One to three inches (76 mm maximum) in diameter. Bite does one point of damage. Two attacks per melee, spd 10, and can climb most surfaces except glass or highly polished metal. Spider (poisonous): Three inches (76 mm) in diameter. Bite does one point of damage plus 4D6 damage (roll to save vs poison - a successful save means no damage). Three attacks per melee, spd 12, and can climb most surfaces except glass or highly polished metal. Snake (poisonous): About four to six feet long (1.2 to 1.8 m). Moves and behaves as a normal snake. Bite inflicts 1D4 S.D.C. damage and releases a poison that causes an additional 4D6 damage (roll to save vs poison - no damage if save is good). Two attacks per melee. +3 to strike and dodge. Wasp or Bee: The same size as the common insects, it behaves as a living bee or wasp. Its sting is painful, causing one S.D.C. point of damage per every two stings. Two attacks per melee, +2 to strike and dodge, spd walking 8, spd flying 37 (25 mph/40 km) and can climb most surfaces except glass or highly polished metal.', NULL, 'tattoo'),
  ('Tattoo: Monsters', 0, 50, '50 for minor monsters with less than 50 M.D.C., 80 for major monsters with 51 to 150 M.D.C., 100 for super monsters with over 151 M.D.C. Twice the cost to re-create a monster that was destroyed, or wait eight hours. Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.90', 'rifts', NULL, '30 minutes per level of the Tattooed Man''s experience, or until slain by depleting its M.D.C., or the magic is cancelled', 'Mega-damage', NULL, NULL, 'One melee action', 'Image: a specific animal-like predatory monster - such as the chimera, dragondactyl, gryphon, harpy, manticore, melech, peryton, and worms of Taut. Intelligent monsters like dragons, eandroth, demons, gromek, minotaurs and elementals are not possible. Each monster is a separate tattoo. The tattoo glows, leaves the body and reappears as a dull grey, life-size monster made of a magic, ectoplasm-like substance. It is an M.D.C. creation with the maximum M.D.C. possible for its type, inflicts mega-damage, acts like the real monster in every way, and only its creator can command or ride it. It is not a familiar. Destroying the monster inflicts 5D6 damage direct to its owner''s hit points, cumulative for each living tattoo destroyed. Stats come from the Rifts Conversion Book or similar sources.', NULL, 'tattoo'),
  ('Tattoo: Chain Encircling a Skull or Brain (psionic save)', 0, 25, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.91', 'rifts', NULL, 'One minute per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Impervious to mind control of all types and +3 to save vs psionic attacks of any kind.', NULL, 'tattoo'),
  ('Tattoo: Chain with a Broken Link (strength)', 0, 30, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.91', 'rifts', NULL, 'Five minutes per level of experience or until cancelled', 'Supernatural P.S. punch damage', NULL, NULL, 'One melee action', 'Instills supernatural strength: mega-damage is inflicted from hand to hand attacks equal to that of supernatural creatures, and the P.S. attribute is temporarily increased by six points. Normal punch damage from supernatural P.S.: P.S. 16-20 1D6 M.D., 21-25 2D6 M.D., 26-30 3D6 M.D., 31-35 4D6 M.D., 36-40 5D6 M.D., 41-50 6D6 M.D. A power punch does double damage and counts as two attacks.', NULL, 'tattoo'),
  ('Tattoo: Chain Wrapped Around a Cloud (air powers)', 0, 50, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.91', 'rifts', NULL, 'One minute per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Influence the elemental forces of air: see the invisible, float in the air, wind rush, call lightning once per melee round, and calm storms, each the same as the spell; see air elementals; communicate with air elementals.', NULL, 'tattoo'),
  ('Tattoo: Cross (turn dead)', 0, 15, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.91', 'rifts', NULL, 'One minute per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Turn dead, equal to the spell.', NULL, 'tattoo'),
  ('Tattoo: Eye with a Dagger In It (blind)', 0, 25, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.91', 'rifts', 'Touch', 'Victims are blinded for one melee per level of the T-Man''s experience; the power to blind by touch lasts one melee (15 seconds) per level of experience', NULL, '16 or higher vs magic', NULL, 'One melee action', 'Blinds an opponent by activating the tattoo and touching the intended victim. Identical to the spell Blind.', NULL, 'tattoo'),
  ('Tattoo: Eye of Knowledge (language)', 0, 15, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.91', 'rifts', NULL, '15 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Understands and speaks all languages equal to a skill of 96%. Literate equal to a skill of 82% - can read and understand most written languages, but not magic symbols, runes, wards or circles. Image: an eye with three equal length lines, one centered over the eye pointing up and two radiating horizontally from each side.', NULL, 'tattoo'),
  ('Tattoo: Eye of Mystic Knowledge (magic)', 0, 20, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.91', 'rifts', NULL, '10 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Can recognize magic circles, symbols, wards, and runes as genuine articles involved in magic. 86% skill in reading and using magic scrolls, 74% recognizing enchantment and possession, 62% reading/identifying specific wards and magic symbols, 50% correctly identifying magic circles, 40% accurately reading runes, 30% correctly identifying a magic item, including weapons and artifacts. Does not enable the character to cast spells, perform rituals or operate circles. Image: an eye in a circle with two equal length lines, often inside a pyramid; a pyramid pointing up means the knowledge works only when used for good, pointing down only for evil, and it will not work contrary to that alignment (nor for selfish motives).', NULL, 'tattoo'),
  ('Tattoo: Eye With Tears (empathy & transmission)', 0, 15, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.91-92', 'rifts', NULL, 'Two minutes per level of experience', NULL, NULL, NULL, 'One melee action', 'Empathy equal to the psionic power, and can perform one empathic transmission as often as once per melee.', NULL, 'tattoo'),
  ('Tattoo: Eyes: Three (supernatural vision)', 0, 20, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', NULL, 'Ten minutes per level of experience', NULL, NULL, NULL, 'One melee action', 'Perfect vision plus nightvision 1200 ft (366 m) in total darkness, see the invisible (including the supernatural), and see aura (same as the psionic power). Bonuses: +1 to strike and +1 on initiative.', NULL, 'tattoo'),
  ('Tattoo: Heart Pierced by a Wooden Stake (protection)', 0, 15, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', NULL, 'One hour per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Impervious to the bite (cannot be turned into a vampire or enslaved) and mind control powers of vampires and related species of undead. A vampire can still hurt and even kill the T-Man with a killing bite attack, punches, claws and weapons. One of the two Marks of Heritage every True Atlantean bears, on the right wrist (printed 86).', NULL, 'tattoo'),
  ('Tattoo: Heart Encircled by Chains (invulnerability)', 0, 40, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', NULL, '10 minutes per level of experience or until the M.D.C. is depleted', NULL, NULL, NULL, 'One melee action', 'Limited invulnerability: the body can withstand 75 M.D. per level of experience. A faint light blue magic aura protects the character and everything on his body from most forms of physical attack, including mega-damage weapons, explosions and falls, poison and drugs. The character is still vulnerable to psionic and magic attacks and can be immobilized and entangled. The magic continues even when the user is rendered unconscious or mind controlled.', NULL, 'tattoo'),
  ('Tattoo: Heart with Large Wings (fly)', 0, 20, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', NULL, '30 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Flight at 50 mph (80 km) plus 10 mph (16 km) per level of experience, to a maximum height of 4000 feet (1200 m). Bonuses: +1 to strike and dodge when flying at levels four, eight and twelve, and +3 to S.D.C. damage from hand to hand attacks. If the user is rendered unconscious or mind controlled he floats 2D6 feet above the ground, drifting with the wind at about five miles (8 km) an hour.', NULL, 'tattoo'),
  ('Tattoo: Heart with Tiny Wings (run)', 0, 10, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', NULL, '30 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Run at superhuman speed: 30 mph (48 km) plus 10 mph (16 km) per level of experience, and leap up to 20 feet (6 m) high or 30 feet (9 m) lengthwise from a running start of at least 30 mph. Bonuses: +1 to dodge when running at levels four, eight and twelve, and +2 to S.D.C. damage from hand to hand attacks. The magic is not cancelled if the user is rendered unconscious, but an unconscious person cannot run.', NULL, 'tattoo'),
  ('Tattoo: Knight in Full Body Armor', 0, 25, 'Twice the cost to re-create armor whose M.D.C. was depleted, or wait eight hours (printed 85). Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', NULL, '30 minutes per level of experience, or until the M.D.C. is depleted or the magic is cancelled', NULL, NULL, NULL, 'One melee action', 'Magic, mega-damage body armor appears on the body of the tattoo user: 20 M.D.C. per level of the T-Man''s experience. The armor is transparent so the other tattoos can still be seen, and the T-Man''s hand passes through it to touch and activate other tattoos, but to all others it is as solid as M.D.C. alloys. Weightless and does not restrict movement. Cannot be placed on anyone other than the T-Man, and does not protect against toxic air, fumes or gases.', NULL, 'tattoo'),
  ('Tattoo: Lightning Bolts (shoot lightning)', 0, 30, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', '200 feet (61 m) plus 100 ft (30.5 m) per level of experience', 'One minute (4 melee rounds) per level of experience or until cancelled', '2D6 M.D. plus 1D6 M.D. per every two levels of experience (2D6 at first level, 3D6 at second, 4D6 at fourth, 5D6 at sixth, and so on); can be regulated in increments of 1D6', NULL, NULL, 'One melee action', 'The tattoo user fires lightning bolts from his hands by pointing and mentally releasing them. Number of attacks: equal to the number of hand to hand attacks. Bonuses: +3 to strike; only P.P. attribute bonuses can be added, not hand to hand or W.P. bonuses.', NULL, 'tattoo'),
  ('Tattoo: Phoenix Rising From the Flames (resurrection)', 0, 124, 'Each resurrection also permanently costs the T-Man 1D6 hit points, 2D6 P.P.E. and one P.E. point, and gains him one M.A. point; a super healing has no such cost. Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', 'Touch or within 12 feet (3.6 m)', 'Instant, with permanent results', NULL, NULL, NULL, 'One melee action', 'Super healing and resurrection of others. A super healing restores up to 50 hit points and 50 S.D.C., or 100 M.D.C. for a mega-damage creature, and cures all common diseases, magic minor disorders, magic sickness, minor curse, and turns a victim of petrification back to flesh. Resurrection is possible only within six hours of death: it brings the dead person up to three hit points, restores missing limbs and organs and heals all wounds without scarring. Addiction, insanity and magic insanity are not cured by either.', NULL, 'tattoo'),
  ('Tattoo: Rose and Thorny Stem & Dripping Blood (heal)', 0, 30, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', 'Touch', 'One minute per level of experience or until cancelled; as many as three healing touches can be performed in one minute', NULL, NULL, NULL, 'One melee action', 'Heal wounds equal to the spell.', NULL, 'tattoo'),
  ('Tattoo: Shark or Dolphin (swim)', 0, 20, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.92', 'rifts', NULL, '30 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Swim as a fish (superior) and breathe without air, equal to the spells.', NULL, 'tattoo'),
  ('Tattoo: Skull with Bat Wings (animate dead)', 0, 30, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.93', 'rifts', NULL, 'Five minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Animate and control dead, same as the spell.', NULL, 'tattoo'),
  ('Tattoo: Skull Coiled with Thorns (death touch)', 0, 40, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.93', 'rifts', 'Touch; penetrates M.D. body armor, but not robot vehicles or power armor', 'Two minutes per level of experience or until cancelled', 'Death touch: an additional 1D6 damage direct to hit points per strike or touch, or 3D6 M.D. to an M.D.C. creature', '16 or higher vs magic; a successful save means no damage from that touch', NULL, 'One melee action', 'An eerie, pale white aura instills +25% to save vs coma/death, +6 to save vs poison and deadly gases/vapors, +6 to save vs horror factor, +1 on all other saving throws, one super bio-regeneration (self: 1D4x10 S.D.C. and 6D6 hit points, or 1D6x10+10 M.D.C. for a mega-damage creature), and the death touch. Death touch attacks: equal to the number of hand to hand attacks. A character killed by a death touch (six or more touches that inflict damage) is -12% to save vs coma/death. Bonuses: +1 to strike and parry. The death touch awakens sleeping victims, and unconscious characters get an automatic saving throw.', NULL, 'tattoo'),
  ('Tattoo: Skull Engulfed in Flames (fire powers)', 0, 45, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.93', 'rifts', '100 ft (30.5 m) per level of experience', 'Five minutes per level of experience or until cancelled', 'Fire bolts: 1D4 M.D. per level of experience, regulated in increments of 1D4', NULL, NULL, 'One melee action', 'Impervious to fire and heat, including magic and mega-damage fires; all other forms of energy do half damage; and a glowing red aura provides 60 M.D.C. of protection (once depleted the other powers remain). Can also shoot bolts of fire from the fingertips. Number of attacks: equal to the number of hand to hand attacks. Bonuses: +2 to strike; only P.P. attribute bonuses can be added.', NULL, 'tattoo'),
  ('Tattoo: Thorns or Ball of Thorns (protection: poison)', 0, 15, 'Double for anyone who is not a full Tattooed Man (printed 85).', NULL, 'import', 'Rifts World Book 2: Atlantis p.93', 'rifts', NULL, '10 minutes per level of experience or until cancelled', NULL, NULL, NULL, 'One melee action', 'Impervious to all forms of poison, and +2 to save vs all types of drugs, chemicals, and gases.', NULL, 'tattoo');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'the 32 tattoos are in' AS assertion, count(*) AS got, 32 AS want
  FROM spells WHERE tradition = 'tattoo' AND name LIKE 'Tattoo: %';
SELECT 'every tattoo is level 0 and cites this book by page' AS assertion, count(*) AS got, 32 AS want
  FROM spells WHERE tradition = 'tattoo' AND level = 0 AND source_book LIKE 'Rifts World Book 2: Atlantis p.%';
SELECT 'the Phoenix costs 124' AS assertion, count(*) AS got, 1 AS want
  FROM spells WHERE name = 'Tattoo: Phoenix Rising From the Flames (resurrection)' AND ppe = 124;
SELECT 'every tattoo says non-T-Men pay double' AS assertion, count(*) AS got, 32 AS want
  FROM spells WHERE tradition = 'tattoo' AND instr(ppe_note, 'Double for anyone') > 0;

